<svg class="zw-map" viewBox="0 0 560 480" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Glowing network map of Zimbabwe connecting its main towns">
<defs>
 <filter id="glow" x="-30%" y="-30%" width="160%" height="160%"><feGaussianBlur stdDeviation="5" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
 <linearGradient id="fillg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#38BDF8" stop-opacity=".28"/><stop offset="1" stop-color="#2563EB" stop-opacity=".16"/></linearGradient>
</defs>
<style>
 .zw-map .outline{fill:url(#fillg);stroke:#7DD3FC;stroke-width:2.2;stroke-linejoin:round;filter:url(#glow);animation:outlinePulse 4s ease-in-out infinite}
 .zw-map .flow{stroke:#7DD3FC;stroke-width:1.6;stroke-dasharray:5 9;stroke-linecap:round;opacity:.9;animation:flowMove 2.4s linear infinite}
 .zw-map .flow1{animation-duration:3.2s;stroke:#38BDF8}.zw-map .flow2{animation-duration:4s;stroke:#BAE6FD;animation-direction:reverse}
 .zw-map .dot{fill:#E0F2FE;stroke:#38BDF8;stroke-width:2;filter:url(#glow)}
 .zw-map .pulse{fill:none;stroke:#38BDF8;stroke-width:1.6;transform-box:fill-box;transform-origin:center;animation:ping 2.6s ease-out infinite}
 .zw-map text{fill:#BAE6FD;font:600 11px "Segoe UI",system-ui,sans-serif;opacity:.9}
 .zw-map .big text{font-size:13px;fill:#fff}
 @keyframes flowMove{to{stroke-dashoffset:-56}}
 @keyframes ping{0%{transform:scale(1);opacity:.9}100%{transform:scale(4.2);opacity:0}}
 @keyframes outlinePulse{0%,100%{stroke-opacity:.75}50%{stroke-opacity:1}}
 @media (prefers-reduced-motion:reduce){.zw-map *{animation:none!important}}
</style>
